'use strict';
// Birthday Match, live version.
// One file, no dependencies. Run with:  node server.js
// Teacher opens the home page and starts a session. Students scan the QR code
// (or type the code) and enter their birthday on their own phone.
//
// Privacy design:
//  - A student's phone turns the birthday into a one-way code (SHA-256 of
//    secret + birthday). Only that code is sent. The secret lives in the link's
//    #fragment, which browsers never send to a server, so this server cannot
//    work the birthdays back out.
//  - Codes are held in memory only, never written to disk, never logged.
//  - When the teacher presses Reveal, the codes are compared for duplicates and
//    erased. Only "match" or "no match" and the number of people remain.
//  - Sessions vanish after 4 hours, or whenever the server restarts.

const http = require('http');
const crypto = require('crypto');

const PORT = process.env.PORT || 3000;
const SESSION_TTL_MS = 4 * 60 * 60 * 1000;
const MAX_ENTRIES = 2000;
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I

const sessions = new Map(); // id -> { key, entries: Map(token -> hash), revealed, touched }

function randomFromAlphabet(len) {
  const bytes = crypto.randomBytes(len);
  let out = '';
  for (let i = 0; i < len; i++) out += ALPHABET[bytes[i] % ALPHABET.length];
  return out;
}
function newSession() {
  let id;
  do { id = randomFromAlphabet(4); } while (sessions.has(id));
  const s = { key: crypto.randomBytes(15).toString('base64url'), entries: new Map(), revealed: null, touched: Date.now() };
  sessions.set(id, s);
  return { id, s };
}
function getSession(id) {
  const s = sessions.get(String(id || '').toUpperCase());
  if (s) s.touched = Date.now();
  return s || null;
}
function keyOk(s, key) {
  if (typeof key !== 'string' || key.length !== s.key.length) return false;
  return crypto.timingSafeEqual(Buffer.from(key), Buffer.from(s.key));
}
setInterval(() => {
  const now = Date.now();
  for (const [id, s] of sessions) if (now - s.touched > SESSION_TTL_MS) sessions.delete(id);
}, 10 * 60 * 1000).unref();

// ---------- helpers ----------
function send(res, status, body, type) {
  const isObj = typeof body !== 'string';
  const data = isObj ? JSON.stringify(body) : body;
  res.writeHead(status, {
    'Content-Type': (type || (isObj ? 'application/json' : 'text/html')) + '; charset=utf-8',
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'no-referrer',
    'Content-Security-Policy': "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'"
  });
  res.end(data);
}
function readJson(req) {
  return new Promise((resolve) => {
    let raw = '';
    req.on('data', (chunk) => { raw += chunk; if (raw.length > 4096) { req.destroy(); resolve(null); } });
    req.on('end', () => { try { resolve(raw ? JSON.parse(raw) : {}); } catch (e) { resolve(null); } });
    req.on('error', () => resolve(null));
  });
}
function publicState(s) {
  return { count: s.entries.size, revealed: s.revealed };
}

