// Illustrations (WebP), served from the server itself.
const IMG_MATCH = Buffer.from('', 'base64');
const IMG_NOMATCH = Buffer.from('', 'base64');
function sendBinary(res, buf, type) { res.writeHead(200, { 'Content-Type': type, 'Content-Length': buf.length, 'Cache-Control': 'public, max-age=86400', 'X-Content-Type-Options': 'nosniff' }); res.end(buf); }

// ---------- shared page parts ----------
const CSS = `
:root{--bg:#f2f6f3;--surface:#fff;--ink:#15201b;--muted:#5a6b63;--line:#d2dcd6;--accent:#1b6f58;--accent-ink:#fff;--accent-soft:#dcefe7;--error:#9a3b25;--error-soft:#f8e4dd;color-scheme:light}
@media (prefers-color-scheme:dark){:root{--bg:#101714;--surface:#19231f;--ink:#e6eeea;--muted:#9db0a7;--line:#2b3934;--accent:#5ccfa4;--accent-ink:#0d1a15;--accent-soft:#1c342c;--error:#f0a089;--error-soft:#3a221c;color-scheme:dark}}
*{box-sizing:border-box}html,body{margin:0}
body{background:var(--bg);color:var(--ink);font-family:"Atkinson Hyperlegible","Segoe UI",system-ui,-apple-system,sans-serif;font-size:18px;line-height:1.5;padding:24px 16px 48px}
[hidden]{display:none!important}
.wrap{max-width:760px;margin:0 auto;display:grid;gap:20px}
h1{font-weight:800;font-size:clamp(1.7rem,4.5vw,2.6rem);line-height:1.1;margin:4px 0 0;text-wrap:balance}
h2{font-weight:700;font-size:clamp(1.3rem,3vw,1.8rem);line-height:1.15;margin:0;text-wrap:balance}
h3{font-size:1.05rem;margin:0 0 8px}
p{margin:0}.muted{color:var(--muted)}.lead{font-size:1.2rem}
.eyebrow{margin:0;font-size:.85rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
.card{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:26px;display:grid;gap:16px}
.row{display:flex;gap:16px;align-items:center;flex-wrap:wrap}
.btn{font:inherit;font-weight:700;padding:14px 22px;border-radius:12px;border:2px solid transparent;cursor:pointer}
.btn.primary{background:var(--accent);color:var(--accent-ink);font-size:1.15rem}
.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}
.btn.link{background:none;padding:4px 0;color:var(--muted);text-decoration:underline;text-underline-offset:3px}
.btn:disabled{opacity:.45;cursor:not-allowed}
input:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}
.inputs{display:flex;gap:16px;flex-wrap:wrap}.field{display:grid;gap:6px}.field label{font-weight:700}
.field input{font:inherit;font-weight:700;font-size:2.6rem;letter-spacing:.25em;width:7.5rem;padding:10px 14px;border:2px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);text-align:center}
.field input::placeholder{color:var(--line);letter-spacing:.05em}
.code-input{font:inherit;font-weight:700;font-size:1.6rem;letter-spacing:.12em;text-transform:uppercase;padding:10px 14px;border:2px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);width:100%;max-width:22rem}
.hint{color:var(--muted);font-size:.95rem}
.msg{min-height:1.5em;font-weight:700}.msg.ok{color:var(--accent)}
.msg.error{color:var(--error);background:var(--error-soft);padding:8px 12px;border-radius:10px}
.check{display:inline-flex;gap:8px;align-items:center;color:var(--muted)}.check input{width:20px;height:20px;accent-color:var(--accent)}
.stat{background:var(--accent-soft);border-radius:14px;padding:18px 22px;display:grid;gap:2px}
.stat-big{font-weight:800;font-size:clamp(3rem,10vw,5.5rem);line-height:1;color:var(--accent);font-variant-numeric:tabular-nums}
.stat-label{font-weight:700}
.join{display:grid;grid-template-columns:auto 1fr;gap:24px;align-items:center}.join-left{display:grid;gap:8px;max-width:300px}
.scene{width:100%;height:auto;max-width:600px;justify-self:center;display:block}.result-scene{max-width:640px;margin:0 auto}
.field select{font:inherit;font-weight:700;font-size:1.45rem;padding:12px 14px;border:2px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);min-width:9rem}
@media (max-width:560px){.join{grid-template-columns:1fr}}
#qr{background:#fff;padding:12px;border-radius:12px;width:max-content;border:1px solid var(--line)}
#qr img,#qr canvas{display:block}
.bigcode{font-weight:800;font-size:clamp(1.5rem,4vw,2rem);letter-spacing:.14em;font-variant-numeric:tabular-nums;line-height:1.2}
.url{font-size:.95rem;color:var(--muted);word-break:break-all}
.result-big{font-size:clamp(1.9rem,5.5vw,3.2rem);line-height:1.1}
.result-big.is-match{color:var(--accent)}
.wiped{border:1px dashed var(--line);border-radius:10px;padding:10px 14px;color:var(--muted);font-size:.95rem}
.privacy{color:var(--muted);font-size:.95rem;padding:0 8px}.privacy ul{margin:0;padding-left:20px;display:grid;gap:4px}
.pill{display:inline-block;padding:4px 12px;border-radius:999px;background:var(--accent-soft);color:var(--accent);font-weight:700;font-size:.9rem}
`;

const SHARED_JS = `
function pMatch(k){if(k<2)return 0;var q=1;for(var j=0;j<k;j++)q*=(365-j)/365;return 1-q}
function pct(p){return (p*100).toFixed(1)+'%'}
function $(id){return document.getElementById(id)}
var ALPHABET='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
function groupCode(s){return s.replace(/(.{4})(?=.)/g,'$1 ')}
`;

function page(title, body, extraHead) {
  return '<!DOCTYPE html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' +
    title + '</title>' + (extraHead || '') + '<style>' + CSS + '</style></head><body><main class="wrap">' + body + '</main></body></html>';
}

const PRIVACY_HTML = `
<footer class="privacy">
  <h3>How privacy is protected</h3>
  <ul>
    <li>Your phone turns the birthday into a one-way code before anything is sent. The secret needed to make that code is only in the link or QR, never on the server, so the server cannot work birthdays back out.</li>
    <li>Codes are held in the server's memory only. Nothing is written to disk and nothing is logged.</li>
    <li>When the teacher reveals the result, all codes are erased. Only "match" or "no match" and the number of people remain.</li>
    <li>Your choice only appears on your own phone screen.</li>
  </ul>
</footer>`;

